structure.mermaidSource:
flowchart TD
  start(["Início: Analisar a sentença proposta"]) --> proc_posicao["Identificar posição do adjetivo"]
  proc_posicao --> dec_posicao{"Qual a posição sintática do adjetivo?"}
  dec_posicao -- "Anteposto" --> proc_atrativa["Identificar gênero e número do 1º substantivo"]
  proc_atrativa --> dec_plural_anteposto{"Apresenta flexão em plural total?"}
  dec_plural_anteposto -- "Sim" --> res_anteposto_invalido["Construção Inválida: Eliminar Alternativa"]
  dec_plural_anteposto -- "Não" --> res_anteposto_valido["Construção Válida: Concordância Atrativa Obrigatória"]
  dec_posicao -- "Posposto" --> dec_posposto_tipo{"Critério adotado na posposição?"}
  dec_posposto_tipo -- "Atrativa" --> res_posposto_atrativa["Construção Válida: Concordância com o Mais Próximo"]
  dec_posposto_tipo -- "Gramatical" --> res_posposto_gramatical["Construção Válida: Plural Total (Prevalência do Masculino)"]

flowchart TD
  start["Início: Localizar adjetivo no texto"] --> proc_pergunta_operacional["Aplicar pergunta operacional:\n'A quais palavras atribui qualidade ou estado?'"]
  proc_pergunta_operacional --> proc_desenhar_setas["Desenhar setas sintático-semânticas\nDo adjetivo para todos os substantivos afetados"]
  proc_desenhar_setas --> dec_qtd_afetados{"O adjetivo qualifica dois ou mais substantivos?"}
  dec_qtd_afetados -- "Sim (2+ substantivos)" --> dec_alt_multiplos{"A alternativa cita todos os substantivos qualificados?"}
  dec_alt_multiplos -- "Não (cita apenas um)" --> res_incorreta_mutilada["Alternativa INCORRETA\nRelação mutilada/falsa"]
  dec_alt_multiplos -- "Sim (lista ambos/todos)" --> res_correta_ambos["Alternativa CORRETA\nRelação integral preservada"]
  dec_qtd_afetados -- "Não (apenas 1 substantivo)" --> dec_alt_unico{"A alternativa aponta o substantivo correto?"}
  dec_alt_unico -- "Sim" --> res_correta_unico["Alternativa CORRETA\nConcordância unívoca direta"]
  dec_alt_unico -- "Não" --> res_incorreta_alheio["Alternativa INCORRETA\nAtribuição sintático-semântica errônea"]
